const invoices = items.map(i => i.json);
const total = invoices.reduce((sum, inv) => sum + (inv.totalGross || 0), 0);
const open = invoices.filter(inv => inv.status === 'OPEN').length;
const paid = invoices.filter(inv => inv.status === 'PAID').length;
const overdue = invoices.filter(inv => inv.status === 'OVERDUE').length;

const rows = invoices.slice(0, 20).map(inv =>
  `<tr><td>${inv.invoiceNumber || '-'}</td><td>${inv.contactName || '-'}</td><td>${(inv.totalGross || 0).toFixed(2)}</td><td>${inv.status}</td></tr>`
).join('');

const html = `
<h2>Daily Invoice Summary</h2>
<p><b>Total Revenue:</b> ${total.toFixed(2)} | <b>Open:</b> ${open} | <b>Paid:</b> ${paid} | <b>Overdue:</b> ${overdue}</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
<tr><th>Invoice #</th><th>Contact</th><th>Amount</th><th>Status</th></tr>
${rows}
</table>
<p style="color:#888;">Generated at ${new Date().toISOString()}</p>`;

return [{ json: { html, total, open, paid, overdue } }];
